def classificar(x,d):
    vistos=set()
    while x!=0:
        if x in vistos: return 'ciclo'
        vistos.add(x); x=(x+d)%4
    return 'parada'
resultados={(x,d):classificar(x,d) for x in range(4) for d in range(4)}
assert len(resultados)==16
assert all(resultados[(0,d)]=='parada' for d in range(4))
assert resultados[(1,2)]=='ciclo'
